solution:
pub enum TaskStatus { Todo, InProgress, Done }

pub type Task = {
  id: Int;
  title: Str;
  status: TaskStatus;
  priority: Int;
}

fn new_task(id: Int, title: Str) -> Task {
  return Task{ id: id, title: title, status: TaskStatus::Todo, priority: 1 };
}

fn main() -> Int {
  let task = new_task(1, "Learn XIOM");
  return task.id;
}
